// Typed fetch client for declarations generated by kanagata.

export type Method =
	| "get"
	| "put"
	| "post"
	| "delete"
	| "options"
	| "head"
	| "patch"
	| "trace"
	| "query";

// Derived from fetch itself, so this file type-checks with Node's types as well as the DOM's.
type HeadersInit = NonNullable<ConstructorParameters<typeof Headers>[0]>;
type BodyInit = NonNullable<RequestInit["body"]>;

type Get<T, K> = K extends keyof T ? T[K] : never;

/** The path templates of P that have method M: `PathsOf<paths, "get">`. */
export type PathsOf<P, M extends string> = {
	[K in keyof P]: M extends keyof P[K] ? K : never;
}[keyof P] &
	string;

type Op<P, Path, M extends string> = Get<Get<P, Path>, M>;

/**
 * The methods of P's path items beyond OpenAPI's fixed fields: the keys of their
 * `additionalOperations` (OpenAPI 3.2), as written, which is how they are sent.
 */
type OtherMethod<P> = Exclude<{ [K in keyof P]: keyof P[K] }[keyof P], Method> &
	string;

/**
 * The methods fetch sends as written: not CONNECT, TRACE and TRACK, which it rejects, nor
 * DELETE, GET, HEAD, OPTIONS, POST and PUT in another case, which it sends in upper case.
 */
type Sendable<M extends string> = M extends unknown
	? Uppercase<M> extends "CONNECT" | "TRACE" | "TRACK"
		? never
		: Uppercase<M> extends
					| "DELETE"
					| "GET"
					| "HEAD"
					| "OPTIONS"
					| "POST"
					| "PUT"
			? never
			: M
	: never;

/** Union of every media type in `content`; `undefined` without content. */
type Content<B> = B extends { content: infer C } ? C[keyof C] : undefined;

/** Whether media type K is M, with or without parameters. */
type IsMedia<K, M extends string> = K extends M | `${M};${string}`
	? true
	: false;

/**
 * Media types whose content is typed by its schema and parsed as JSON: JSON ones, and the
 * wildcards that could be JSON (`*\/*`, `application/*`), as `isBinaryMedia` leaves them.
 */
type KeepsSchema<K> = K extends
	| "application/json"
	| `application/json;${string}`
	| `${string}+json`
	| `${string}+json;${string}`
	| "*/*"
	| `*/*;${string}`
	| "application/*"
	| `application/*;${string}`
	? true
	: false;

/** What `parseAs: "json"` gives: the schema of JSON media types, unknown for the others. */
type JsonContent<B> = B extends { content: infer C }
	? { [K in keyof C]: KeepsSchema<K> extends true ? C[K] : unknown }[keyof C]
	: undefined;

/** The raw bodies the client sends as they are (`isRawBody`) for a binary media type. */
type RawBinary =
	| Blob
	| ArrayBuffer
	| ArrayBufferView<ArrayBuffer>
	| ReadableStream<Uint8Array>;

/**
 * A body of schema type T: any raw binary body where a Blob is (binary media types are
 * Blob), and never undefined, which is no body.
 */
type BodyOf<T> = unknown extends T
	? NonNullable<unknown> | null
	: Blob extends T
		? T | RawBinary
		: T;

/**
 * How a body of media type K is passed. contentType picks the media type and so the
 * encoding; it may be left out for application/json, which is what is sent then, and
 * for a FormData or URLSearchParams, which carry their own.
 */
type BodyVariant<K, T> =
	IsMedia<K, "application/json"> extends true
		? { contentType?: K; body: BodyOf<T> }
		: IsMedia<K, "multipart/form-data"> extends true
			?
					| { contentType: K; body: BodyOf<T> }
					| { contentType?: K; body: FormData }
			: IsMedia<K, "application/x-www-form-urlencoded"> extends true
				?
						| { contentType: K; body: BodyOf<T> }
						| { contentType?: K; body: URLSearchParams }
				: { contentType: K; body: BodyOf<T> };

type BodyVariants<B> = B extends { content: infer C }
	? { [K in keyof C & string]: BodyVariant<K, C[K]> }[keyof C & string]
	: never;

/** An object type with no required keys; `Empty extends T` asks whether everything in T is optional. */
type Empty = Record<never, never>;

type Params<O> = O extends { parameters: infer X } ? X : Empty;

type Body<O> = "requestBody" extends keyof O
	? Empty extends Pick<O, "requestBody" & keyof O>
		?
				| BodyVariants<NonNullable<Get<O, "requestBody">>>
				| { body?: undefined; contentType?: undefined }
		: BodyVariants<Get<O, "requestBody">>
	: Empty;

/** How to read response bodies; left out, by the content-type (JSON, text, or Blob for binary types). */
export type ParseAs = "json" | "text" | "blob" | "arrayBuffer" | "stream";

/**
 * Arrays in queries and URL-encoded bodies: `ids=1&ids=2` (repeat, default),
 * `ids%5B%5D=1&ids%5B%5D=2` (brackets), `ids=1,2` (comma), `ids=1%202` (space),
 * `ids=1%7C2` (pipe).
 */
export type ArrayFormat = "repeat" | "brackets" | "comma" | "space" | "pipe";

/** Objects in queries and URL-encoded bodies: `a%5Bb%5D=1` (deepObject, default) or `a={"b":1}` (json). */
export type ObjectFormat = "deepObject" | "json";

/**
 * fetch's own options (credentials, cache, mode, redirect, keepalive, signal, …), per
 * client or per call; a call's win. The client sets method, headers and body.
 */
export type FetchOptions = Omit<RequestInit, "method" | "headers" | "body">;

export interface RequestOptions extends FetchOptions {
	/** Headers for this call only (separate from header parameters). */
	headers?: HeadersInit;
	/** Overrides the client's arrayFormat for this call. */
	arrayFormat?: ArrayFormat;
	/** Overrides the client's objectFormat for this call. */
	objectFormat?: ObjectFormat;
}

/**
 * Where operation O is sent: an operation that declares servers is served by one of
 * them, named as the call's baseUrl; any other by the client's baseUrl.
 */
type Server<O> = O extends { servers: infer S extends readonly unknown[] }
	? { baseUrl: S[number] }
	: { baseUrl?: never };

/** What a call's options must hold for operation O: its parameters, body and server. */
type Needs<O> = Params<O> & Body<O> & Server<O>;

/**
 * For a union of operations (a union of paths), what every one of them needs: one init
 * serves whichever is called. For one operation, its own needs.
 */
type NeedsAll<O> = Get<
	(O extends unknown ? (n: { needs: Needs<O> }) => void : never) extends (
		n: infer I,
	) => void
		? I
		: never,
	"needs"
>;

type Init<N, A> = N & RequestOptions & { parseAs?: A };

/**
 * The arguments after the path of `client[M](path, …)`: the options, optional when nothing
 * in them is required. With `PathsOf` and `ResultOf`, it types a function that wraps a call:
 * `(path: Path, ...args: ArgsOf<paths, "get", Path, A>) => api.get<Path, A>(path, ...args)`;
 * TypeScript cannot infer A through the spread, so the call names it.
 */
export type ArgsOf<
	P,
	M extends string,
	Path extends PathsOf<P, M>,
	A extends ParseAs | undefined = undefined,
> =
	Empty extends NeedsAll<Op<P, Path, M>>
		? [init?: Init<NeedsAll<Op<P, Path, M>>, A>]
		: [init: Init<NeedsAll<Op<P, Path, M>>, A>];

/** "2XX" and default have no single status. */
type Status<S> = S extends number ? S : number;
/** Whether a status key is a success: `200`…`299` or `"2XX"`. */
type IsSuccess<S> = S extends number
	? `${S}` extends `2${string}`
		? true
		: false
	: S extends "2XX"
		? true
		: false;

/** `ok` per status, as fetch sets it. `default` covers any undocumented status, 2xx included. */
type Ok<S> = S extends "default" ? boolean : IsSuccess<S>;

/** `data` for a response object B (its `content`), read as parseAs A says. */
type Parsed<A, B> = A extends "text"
	? string
	: A extends "blob"
		? Blob
		: A extends "arrayBuffer"
			? ArrayBuffer
			: A extends "stream"
				? ReadableStream<Uint8Array> | null
				: A extends "json"
					? JsonContent<B>
					: Content<B>;

/** fetch gives HEAD responses and these statuses a null body, whatever is declared. */
type NullBodyStatus = 204 | 205 | 304;

/** The response object as fetch delivers it: without content where fetch gives no body. */
type Delivered<M, S, B> = [M] extends ["head"]
	? Empty
	: S extends NullBodyStatus
		? Empty
		: B;

/** A response nothing documents: any status, any body. */
type Undocumented = { content: Record<string, unknown> };

/** Discriminated union over the documented statuses. */
export type Result<
	O,
	A extends ParseAs | undefined = undefined,
	M extends string = Method,
> = O extends {
	responses: infer R;
}
	? [keyof R] extends [never]
		? {
				status: number;
				ok: boolean;
				data: Parsed<A, Undocumented>;
				response: Response;
			}
		: {
				[S in keyof R]: {
					status: Status<S>;
					ok: Ok<S>;
					data: Parsed<A, Delivered<M, S, R[S]>>;
					response: Response;
				};
			}[keyof R]
	: never;

/**
 * What `client[M](path, { parseAs: A })` resolves to, named in the order of the call:
 * `ResultOf<paths, "get", "/users/{id}">`. `Result` of the path's operation, with the
 * method given once (so HEAD has no body, as in the call).
 */
export type ResultOf<
	P,
	M extends string,
	Path extends PathsOf<P, M>,
	A extends ParseAs | undefined = undefined,
> = Result<Op<P, Path, M>, A, M>;

/**
 * The results of R that `if (res.ok)` leaves: the 2xx statuses, and `default`, which
 * covers an undocumented 2xx (its `ok` is `boolean`). `OkResult<ResultOf<…>>["data"]`
 * types what a wrapper returns when it throws the others.
 */
export type OkResult<R> = R extends { ok: infer K }
	? true extends K
		? R & { ok: true }
		: never
	: never;

/** The results of R that `if (!res.ok)` leaves: the other statuses, and `default`. */
export type NotOkResult<R> = R extends { ok: infer K }
	? false extends K
		? R & { ok: false }
		: never
	: never;

type MaybePromise<T> = T | Promise<T>;

export interface ClientConfig extends FetchOptions {
	/** Absolute, or relative to the page (`/api`) as fetch resolves it, on every call. */
	baseUrl: string;
	/**
	 * Replaces the global fetch. It is called with the built Request and returns the
	 * Response to read: wrap the global fetch here for auth, retries, logging or tests.
	 */
	fetch?: (request: Request) => Promise<Response>;
	/**
	 * Headers for every request; a function (sync or async) is called on every request.
	 * A call's header and cookie parameters and `headers` replace them by name. A
	 * content-type here is never sent: the body decides it.
	 */
	headers?: HeadersInit | (() => MaybePromise<HeadersInit>);
	/** Arrays in queries and URL-encoded bodies; `repeat` when left out. */
	arrayFormat?: ArrayFormat;
	/** Objects in queries and URL-encoded bodies; `deepObject` when left out. */
	objectFormat?: ObjectFormat;
	/**
	 * Receives every parsed body; what it returns becomes `data`. The place for runtime
	 * validation (zod, valibot, …): pick a schema by `call.path` and `call.status`, and
	 * throw when the body does not match. The result is still typed by the OpenAPI schema.
	 */
	onData?: (data: unknown, call: DataCall) => MaybePromise<unknown>;
}

/**
 * Which call a body answers. `method` is the client function's name (`get`), or the
 * method given to `request` (`COPY`); `path` is the template as written, such as `/users/{id}`.
 */
export interface DataCall {
	method: string;
	path: string;
	status: number;
	parseAs: ParseAs | undefined;
	request: Request;
	response: Response;
}

type Call<P, M extends Method> = <
	Path extends PathsOf<P, M>,
	A extends ParseAs | undefined = undefined,
>(
	path: Path,
	...args: ArgsOf<P, M, Path, A>
) => Promise<ResultOf<P, M, Path, A>>;

/** A call by a method of `additionalOperations`, named first: `request("COPY", path, init)`. */
type OtherCall<P> = <
	M extends Sendable<OtherMethod<P>>,
	Path extends PathsOf<P, M>,
	A extends ParseAs | undefined = undefined,
>(
	method: M,
	path: Path,
	...args: ArgsOf<P, M, Path, A>
) => Promise<ResultOf<P, M, Path, A>>;

/**
 * A function per method fetch sends: every fixed one but TRACE, which fetch rejects, and
 * `request` for the methods of `additionalOperations`.
 */
export type Client<P> = { [M in Exclude<Method, "trace">]: Call<P, M> } & {
	request: OtherCall<P>;
};

interface AnyInit extends RequestOptions {
	baseUrl?: string;
	path?: Record<string, unknown>;
	query?: Record<string, unknown>;
	querystring?: unknown;
	header?: Record<string, unknown>;
	cookie?: Record<string, unknown>;
	body?: unknown;
	contentType?: string;
	parseAs?: ParseAs;
}

interface AnyResult {
	status: number;
	ok: boolean;
	data: unknown;
	response: Response;
}

/** Keys of ClientConfig and of a call's init that are the client's, not fetch's. */
const OWN_KEYS = new Set([
	"baseUrl",
	"fetch",
	"headers",
	"arrayFormat",
	"objectFormat",
	"onData",
	"path",
	"query",
	"querystring",
	"header",
	"cookie",
	"body",
	"contentType",
	"parseAs",
	"method",
]);

/** The fetch options in a config or init: every other key that is set. */
function fetchOptions(options: object): FetchOptions {
	return Object.fromEntries(
		Object.entries(options).filter(
			([key, value]) => !OWN_KEYS.has(key) && value !== undefined,
		),
	);
}

/** The HTTP methods of a Path Item, in OpenAPI's order. The generator reads them from here too. */
export const METHODS: readonly Method[] = [
	"get",
	"put",
	"post",
	"delete",
	"options",
	"head",
	"patch",
	"trace",
	"query",
];

/**
 * The base URL of a call. A relative one (`/api`) resolves as fetch resolves a relative URL:
 * against the document's base URL, or the worker's location; with neither it throws.
 */
function resolveBase(baseUrl: string): URL {
	const scope = globalThis as {
		document?: { baseURI: string };
		location?: { href: string };
	};
	const page = scope.document?.baseURI ?? scope.location?.href;
	let url: URL;
	try {
		// "" is the origin of the page's base URL, as in fetch("" + path); resolved, it would be the page itself.
		url = new URL(baseUrl === "" ? "/" : baseUrl, page);
	} catch {
		throw new TypeError(
			`baseUrl ${JSON.stringify(baseUrl)} is not a URL${page === undefined ? " (a relative one needs a page to resolve against)" : ""}`,
		);
	}
	// `localhost:3000/api` is a URL of the scheme `localhost:`, which has no origin.
	if (url.origin === "null")
		throw new TypeError(
			`baseUrl ${JSON.stringify(baseUrl)} has no origin: write its scheme (https://…)`,
		);
	return url;
}

/**
 * A client for the `paths` that `kanagata generate` declares: one function per HTTP
 * method, `api.get("/users/{id}", { path: { id: 1 } })`, resolving to a union over the
 * documented statuses. HTTP error statuses do not throw.
 */
export function createClient<P>(config: ClientConfig): Client<P> {
	async function send(
		method: string,
		path: string,
		init: AnyInit = {},
	): Promise<AnyResult> {
		// The base keeps its own query; paths go after its path, queries after its query.
		const base = resolveBase(init.baseUrl ?? config.baseUrl);
		const formats: Formats = {
			array: init.arrayFormat ?? config.arrayFormat ?? "repeat",
			object: init.objectFormat ?? config.objectFormat ?? "deepObject",
		};
		const query = [
			base.search.slice(1),
			urlEncode(init.query ?? {}, formats),
			queryString(init.querystring, formats),
		]
			.filter((q) => q !== "")
			.join("&");
		const url = `${base.origin}${base.pathname.replace(/\/+$/, "")}${fillPath(path, init.path)}${query === "" ? "" : `?${query}`}`;

		const headers = new Headers();
		const shared =
			typeof config.headers === "function"
				? await config.headers()
				: config.headers;
		copyHeaders(headers, shared);
		// The body decides content-type, or the call's headers; never the client's.
		headers.delete("content-type");
		for (const [name, value] of Object.entries(init.header ?? {})) {
			const parts = simple(value);
			if (parts.length > 0) headers.set(name, parts.join(","));
		}
		// Browsers do not let fetch set this header; their cookies come from the cookie jar.
		const cookie = buildCookie(init.cookie);
		if (cookie !== "") headers.set("cookie", cookie);
		copyHeaders(headers, init.headers);

		const requestInit: RequestInit & { duplex?: "half" } = {
			...fetchOptions(config),
			...fetchOptions(init),
			// A method of additionalOperations is sent as written; the fixed ones in upper case.
			method: (METHODS as readonly string[]).includes(method)
				? method.toUpperCase()
				: method,
			headers,
		};
		if (init.body !== undefined) {
			requestInit.body = await encodeBody(
				init.body,
				init.contentType,
				headers,
				formats,
			);
		}
		if (requestInit.body instanceof ReadableStream) requestInit.duplex = "half";

		const request = new Request(url, requestInit);
		const response = await (config.fetch ?? globalThis.fetch)(request);
		let data = await readData(response, init.parseAs);
		if (config.onData !== undefined) {
			const { status } = response;
			data = await config.onData(data, {
				method,
				path,
				status,
				parseAs: init.parseAs,
				request,
				response,
			});
		}
		return { status: response.status, ok: response.ok, data, response };
	}

	const client: Partial<
		Record<Method, (path: string, init?: AnyInit) => Promise<AnyResult>>
	> & {
		request?: (
			method: string,
			path: string,
			init?: AnyInit,
		) => Promise<AnyResult>;
	} = {};
	for (const method of METHODS) {
		if (method !== "trace")
			client[method] = (path, init) => send(method, path, init);
	}
	client.request = send;
	return client as unknown as Client<P>;
}

/**
 * A querystring parameter (OpenAPI 3.2), the whole query: an object is URL-encoded as
 * a query is; a string, the text of another media type, is percent-encoded as one value.
 */
function queryString(value: unknown, formats: Formats): string {
	if (value == null) return "";
	if (typeof value === "string") return encodeURIComponent(value);
	return urlEncode(value as Record<string, unknown>, formats);
}

/**
 * Encodes a body by its contentType and sets content-type for it, unless the call's
 * headers did: a value is JSON without a contentType, a form for a form media type; a
 * raw body (string, Blob, FormData, …) is sent as it is, except a string as JSON.
 */
async function encodeBody(
	value: unknown,
	requested: string | undefined,
	headers: Headers,
	formats: Formats,
): Promise<BodyInit> {
	// A wildcard (`*/*`, `application/*`) names no media type, so it sets no content-type:
	// a raw body (a string too) carries its own, a value goes as application/json.
	const wildcard = requested?.includes("*") === true;
	const contentType = wildcard ? undefined : requested;
	const type = contentType === undefined ? undefined : essence(contentType);
	const set = (t: string | undefined) => {
		if (t !== undefined && !headers.has("content-type"))
			headers.set("content-type", t);
	};
	if (value instanceof FormData) {
		// fetch sets content-type with the boundary.
		headers.delete("content-type");
		return value;
	}
	const raw = isRawBody(value);
	// A form is made of the fields of an object.
	const fields = (form: string) => {
		if (typeof value !== "object" || value === null)
			throw new TypeError(
				`a ${form} body must be an object: ${JSON.stringify(value)}`,
			);
		return value as Record<string, unknown>;
	};
	if (type?.startsWith("multipart/") && !raw) {
		const form = new FormData();
		formFields(fields(type), (name, field) => form.append(name, field));
		headers.delete("content-type");
		// fetch sets content-type with the boundary.
		if (type === "multipart/form-data") return form;
		// fetch writes only multipart/form-data; its parts are named by the object's
		// properties, which other multipart types allow (OpenAPI 3.1.1, "Encoding
		// multipart Media Types").
		const encoded = new Response(form);
		const formType = encoded.headers.get("content-type") as string;
		headers.set("content-type", formType.replace("multipart/form-data", type));
		return encoded.blob();
	}
	if (type === "application/x-www-form-urlencoded" && !raw) {
		set(contentType);
		return urlEncode(fields(type), formats);
	}
	// A JSON body is the JSON text of the value, a string included; other bodies are sent as they are.
	const json = type === undefined ? !wildcard : isJsonMedia(type);
	if (raw && !(json && typeof value === "string")) {
		set(contentType);
		return value;
	}
	set(contentType ?? "application/json");
	return JSON.stringify(value);
}

/**
 * The parts of a path, header or cookie parameter: arrays `1,2`, objects `x,1,y,2`.
 * undefined and null are left out, as in queries, so these may be none.
 */
function simple(value: unknown): string[] {
	const parts =
		value == null
			? []
			: Array.isArray(value)
				? value.filter((v) => v != null)
				: typeof value === "object" && !(value instanceof Date)
					? Object.entries(value)
							.filter(([, v]) => v != null)
							.flat()
					: [value];
	return parts.map(scalar);
}

/**
 * A path parameter the URL cannot carry: missing, or one that would change the path (`""`,
 * `.`, `..`). Thrown before anything is sent; a TypeError, which fetch's network errors are too.
 * `parameter` is its name in the path template (`id` in `/users/{id}`), `value` what was given.
 */
export class PathParameterError extends TypeError {
	override readonly name = "PathParameterError";
	readonly parameter: string;
	readonly value: unknown;

	constructor(message: string, parameter: string, value: unknown) {
		super(message);
		this.parameter = parameter;
		this.value = value;
	}
}

/** Path parameters in the simple style, each part encoded. */
function fillPath(path: string, params: Record<string, unknown> = {}): string {
	return path.replace(/\{([^}]+)\}/g, (_, name: string) => {
		const value = params[name];
		if (value == null)
			throw new PathParameterError(
				`missing path parameter: ${name}`,
				name,
				value,
			);
		const segment = simple(value).map(encodeURIComponent).join(",");
		// URLs resolve `.` and `..` segments, so these would reach another endpoint.
		if (segment === "" || segment === "." || segment === "..")
			throw new PathParameterError(
				`path parameter ${name} would change the path: ${JSON.stringify(value)}`,
				name,
				value,
			);
		return segment;
	});
}

interface Formats {
	array: ArrayFormat;
	object: ObjectFormat;
}

/**
 * `a=1&b%5Bc%5D=2`: a query string, or a URL-encoded body. The delimiters `[`, `]`
 * and `|` are percent-encoded, as OpenAPI requires. undefined and null are left out.
 */
function urlEncode(fields: Record<string, unknown>, formats: Formats): string {
	const parts: string[] = [];
	for (const [name, value] of Object.entries(fields))
		serialize(parts, encodeURIComponent(name), value, formats);
	return parts.join("&");
}

const JOINERS: Partial<Record<ArrayFormat, string>> = {
	comma: ",",
	space: "%20",
	pipe: "%7C",
};

function serialize(
	parts: string[],
	key: string,
	value: unknown,
	formats: Formats,
): void {
	if (value == null) return;
	if (value instanceof Blob)
		throw new TypeError(
			`a Blob cannot be URL-encoded: ${decodeURIComponent(key)}`,
		);
	if (Array.isArray(value)) {
		// Items are text: an object or array inside is JSON.
		const items: string[] = [];
		for (const item of value) {
			if (item == null) continue;
			if (item instanceof Blob)
				throw new TypeError(
					`a Blob cannot be URL-encoded: ${decodeURIComponent(key)}`,
				);
			items.push(encodeURIComponent(scalar(item)));
		}
		const joiner = JOINERS[formats.array];
		if (joiner !== undefined) {
			if (items.length > 0) parts.push(`${key}=${items.join(joiner)}`);
			return;
		}
		const itemKey = formats.array === "brackets" ? `${key}%5B%5D` : key;
		for (const item of items) parts.push(`${itemKey}=${item}`);
	} else if (typeof value === "object" && !(value instanceof Date)) {
		if (formats.object === "json") {
			parts.push(`${key}=${encodeURIComponent(JSON.stringify(value))}`);
			return;
		}
		for (const [name, item] of Object.entries(value)) {
			serialize(
				parts,
				`${key}%5B${encodeURIComponent(name)}%5D`,
				item,
				formats,
			);
		}
	} else {
		parts.push(`${key}=${encodeURIComponent(scalar(value))}`);
	}
}

/** One value as text: dates in ISO form, objects as JSON. */
function scalar(value: unknown): string {
	if (value instanceof Date) return value.toISOString();
	return typeof value === "object" && value !== null
		? JSON.stringify(value)
		: String(value);
}

/**
 * The fields of an object body for multipart/form-data: arrays repeat the field, Blobs
 * are files, dates are ISO strings, other objects are JSON (the OpenAPI default for
 * multipart), and undefined and null are left out.
 */
function formFields(
	body: unknown,
	add: (name: string, value: string | Blob) => void,
): void {
	const one = (name: string, value: unknown) => {
		if (value == null) return;
		if (value instanceof Blob) add(name, value);
		else if (typeof value === "object" && !(value instanceof Date))
			add(name, JSON.stringify(value));
		else add(name, scalar(value));
	};
	for (const [name, value] of Object.entries(body as Record<string, unknown>)) {
		if (Array.isArray(value)) for (const item of value) one(name, item);
		else one(name, value);
	}
}

/**
 * `a=1; ids=1,2; p=x,1,y,2` (form style, the values of `simple`), each part encoded;
 * a cookie with no parts is left out.
 */
function buildCookie(cookie: Record<string, unknown> = {}): string {
	const cookies: string[] = [];
	for (const [name, value] of Object.entries(cookie)) {
		const parts = simple(value);
		if (parts.length > 0)
			cookies.push(`${name}=${parts.map(encodeURIComponent).join(",")}`);
	}
	return cookies.join("; ");
}

function copyHeaders(target: Headers, source: HeadersInit | undefined): void {
	if (source === undefined) return;
	for (const [name, value] of new Headers(source)) target.set(name, value);
}

function isRawBody(body: unknown): body is BodyInit {
	return (
		typeof body === "string" ||
		body instanceof FormData ||
		body instanceof Blob ||
		body instanceof URLSearchParams ||
		body instanceof ArrayBuffer ||
		ArrayBuffer.isView(body) ||
		body instanceof ReadableStream
	);
}

/** A response body, read by parseAs or by its content-type; empty is undefined. */
async function readData(
	response: Response,
	parseAs: ParseAs | undefined,
): Promise<unknown> {
	switch (parseAs) {
		case "text":
			return response.text();
		case "blob":
			return response.blob();
		case "arrayBuffer":
			return response.arrayBuffer();
		case "stream":
			return response.body;
		case "json":
			return parseJson(response, await response.text());
	}
	// HEAD and 204, 205, 304 responses have a null body under fetch, so they are empty here too.
	const type = response.headers.get("content-type") ?? "";
	if (type !== "" && isBinaryMedia(type)) {
		const blob = await response.blob();
		return blob.size === 0 ? undefined : blob;
	}
	const text = await response.text();
	if (text === "") return undefined;
	return isJsonMedia(type) ? parseJson(response, text) : text;
}

/** A body that is not valid JSON where its content-type (or parseAs) says JSON, such as an HTML error page. */
export class ResponseBodyError extends Error {
	override readonly name = "ResponseBodyError";
	readonly response: Response;
	readonly text: string;

	constructor(response: Response, text: string, cause: unknown) {
		super(`response body is not valid JSON (status ${response.status})`, {
			cause,
		});
		this.response = response;
		this.text = text;
	}
}

function parseJson(response: Response, text: string): unknown {
	if (text === "") return undefined;
	try {
		return JSON.parse(text);
	} catch (e) {
		throw new ResponseBodyError(response, text, e);
	}
}

/** The media type without parameters, in lower case: `Text/HTML; charset=utf-8` → `text/html`. */
function essence(mediaType: string): string {
	const semicolon = mediaType.indexOf(";");
	return (semicolon < 0 ? mediaType : mediaType.slice(0, semicolon))
		.trim()
		.toLowerCase();
}

function isJsonMedia(mediaType: string): boolean {
	const mt = essence(mediaType);
	return mt === "application/json" || mt.endsWith("+json");
}

/**
 * Whether a body of this media type is raw bytes: anything but JSON, text, XML, forms
 * and wildcards that could be any of those (`*\/*`, `application/*`). The client reads
 * such responses as Blob, and the generator types such content as Blob, by this one rule.
 */
export function isBinaryMedia(mediaType: string): boolean {
	const mt = essence(mediaType);
	if (
		mt === "*/*" ||
		mt === "application/*" ||
		isJsonMedia(mt) ||
		isTextMedia(mt)
	)
		return false;
	return !isFormMedia(mt);
}

/**
 * Whether a body of this media type is a form: sent from an object (URL-encoded, or
 * as FormData), and, as a response, read as its text. The generator types form
 * responses as `string` by this rule.
 */
export function isFormMedia(mediaType: string): boolean {
	const mt = essence(mediaType);
	return (
		mt.startsWith("multipart/") || mt === "application/x-www-form-urlencoded"
	);
}

/**
 * Whether a body of this media type is text the client reads and sends as a string:
 * `text/*` and XML. The generator types such content as `string` by this rule.
 */
export function isTextMedia(mediaType: string): boolean {
	const mt = essence(mediaType);
	return (
		mt.startsWith("text/") || mt === "application/xml" || mt.endsWith("+xml")
	);
}
